using GraphApi.Models.SGR.PerfilMenus;namespace GraphApi.Services.SGR.PerfilMenus{    /// <summary>    /// Define las operaciones de negocio y persistencia para PerfilMenus.    /// </summary>    public interface IPerfilMenusService    {        /// <summary>        /// Obtiene la lista de PerfilMenus con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadPerfilMenus>> GetPerfilMenus(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de PerfilMenus con filtros opcionales.        /// </summary>        /// <param name="perfilMenuID">Filtro opcional para PerfilMenuID.</param>        /// <param name="perfilID">Filtro opcional para PerfilID.</param>        /// <param name="perfil">Filtro opcional para Perfil.</param>        /// <param name="menuID">Filtro opcional para MenuID.</param>        /// <param name="tituloMenu">Filtro opcional para TituloMenu.</param>        /// <param name="icono">Filtro opcional para Icono.</param>        /// <param name="ruta">Filtro opcional para Ruta.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetPerfilMenusDynamic(            int? perfilMenuID,            int? perfilID,            string? perfil,            int? menuID,            string? tituloMenu,            string? icono,            string? ruta,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo PerfilMenu.        /// </summary>        /// <param name="objInput">Datos para crear el PerfilMenu.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadPerfilMenus> CreatePerfilMenus(            clCreatePerfilMenus objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un PerfilMenu.        /// </summary>        /// <param name="objInput">Datos para actualizar el PerfilMenu, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadPerfilMenus?> UpdatePerfilMenus(            clUpdatePerfilMenus objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un PerfilMenu por su ID.        /// </summary>        /// <param name="nPerfilMenusID">ID del PerfilMenu a eliminar.</param>        Task<bool> DeletePerfilMenus(int nPerfilMenusID);    }}